func TestOperations(t *testing.T) {
	ids := map[string]bool{}
	for _, c := range operationCases {
		ids[c.id] = true
	}
	if len(ids) != 144 {
		t.Fatalf("%d operations have a case, want 144", len(ids))
	}
	type received struct {
		method, path string
		body         []byte
	}
	var mu sync.Mutex
	var requests []received
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		mu.Lock()
		requests = append(requests, received{r.Method, strings.SplitN(r.RequestURI, "?", 2)[0], body})
		mu.Unlock()
		w.Header().Set("Content-Type", "application/json")
		_, _ = io.WriteString(w, "{}")
	}))
	defer server.Close()
	client, err := NewClient(WithAPIKey(testKey), WithBaseURL(server.URL))
	if err != nil {
		t.Fatal(err)
	}
	for _, c := range operationCases {
		t.Run(c.id, func(t *testing.T) {
			mu.Lock()
			requests = nil
			mu.Unlock()
			if err := c.call(context.Background(), client); err != nil {
				t.Fatalf("error %v", err)
			}
			mu.Lock()
			defer mu.Unlock()
			if len(requests) != 1 {
				t.Fatalf("%d requests, want 1", len(requests))
			}
			got := requests[0]
			if got.method != c.method || got.path != c.path {
				t.Fatalf("sent %s %s, want %s %s", got.method, got.path, c.method, c.path)
			}
			if c.body == "" {
				return
			}
			var sent, want any
			if err := json.Unmarshal(got.body, &sent); err != nil {
				t.Fatalf("body %q is not JSON: %v", got.body, err)
			}
			mustDecode(c.body, &want)
			if !reflect.DeepEqual(sent, want) {
				t.Fatalf("body %s, want %s", got.body, c.body)
			}
		})
	}
}
